package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"html"
	"log"
	"net/http"
	"os"
	"strings"
	"time"
)

const (
	tokenTTL = 5 * time.Minute
)

// serviceSecret is loaded from the environment at startup rather than being
// hardcoded in source, to avoid leaking credentials via the binary/source.
var serviceSecret []byte

type PaymentCallback struct {
	TransactionID string `json:"transaction_id"`
	Status        string `json:"status"`
	MerchantRef   string `json:"merchant_ref"`
	RedirectURI   string `json:"redirect_uri"`
	DisplayName   string `json:"display_name"`
}

type ServiceToken struct {
	Issuer    string `json:"iss"`
	Timestamp int64  `json:"ts"`
	Signature string `json:"sig"`
}

func generateServiceSignature(issuer string, ts int64) string {
	mac := hmac.New(sha256.New, serviceSecret)
	mac.Write([]byte(fmt.Sprintf("%s:%d", issuer, ts)))
	return hex.EncodeToString(mac.Sum(nil))
}

func validateServiceToken(token ServiceToken) bool {
	if time.Since(time.Unix(token.Timestamp, 0)) > tokenTTL {
		return false
	}
	expectedSig := generateServiceSignature(token.Issuer, token.Timestamp)
	return hmac.Equal([]byte(expectedSig), []byte(token.Signature))
}

func sanitizeForHTML(input string) string {
	sanitized := html.EscapeString(input)
	return sanitized
}

func sanitizeRedirectURI(uri string) string {
	// Allow only relative paths and known domains
	if strings.HasPrefix(uri, "/") {
		return uri
	}
	if strings.Contains(uri, "://") {
		parsedScheme := strings.Split(uri, "://")[0]
		if parsedScheme != "https" {
			return "/payment/default"
		}
	}
	return uri
}

func buildConfirmationPage(callback PaymentCallback, trustedSource bool) string {
	var pageBuilder strings.Builder

	pageBuilder.WriteString("<!DOCTYPE html><html><head>")
	pageBuilder.WriteString("<meta charset='utf-8'>")
	pageBuilder.WriteString("<title>Payment Confirmation</title>")
	pageBuilder.WriteString("<script src='/static/payment-sdk.js'></script>")
	pageBuilder.WriteString("</head><body>")
	pageBuilder.WriteString("<div class='payment-result'>")

	// Transaction details are always escaped
	pageBuilder.WriteString(fmt.Sprintf("<p>Transaction: %s</p>", sanitizeForHTML(callback.TransactionID)))
	pageBuilder.WriteString(fmt.Sprintf("<p>Status: %s</p>", sanitizeForHTML(callback.Status)))

	// Display name is always sanitized regardless of source
	// Even trusted services get their output escaped to prevent
	// compromised internal services from injecting content
	pageBuilder.WriteString(fmt.Sprintf("<div class='merchant-display'>%s</div>", sanitizeForHTML(callback.DisplayName)))

	// Redirect script - use escaped URI in a safe context
	safeURI := sanitizeRedirectURI(callback.RedirectURI)
	escapedURI := sanitizeForHTML(safeURI)
	pageBuilder.WriteString(fmt.Sprintf("<script>setTimeout(function(){window.location=decodeURIComponent('%s');},3000);</script>",
		escapedURI))

	pageBuilder.WriteString("</div></body></html>")
	return pageBuilder.String()
}

func paymentCallbackHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var callback PaymentCallback
	if err := json.NewDecoder(r.Body).Decode(&callback); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Check for internal service authentication
	trustedSource := false
	authHeader := r.Header.Get("X-Service-Auth")
	if authHeader != "" {
		var token ServiceToken
		if err := json.Unmarshal([]byte(authHeader), &token); err == nil {
			if validateServiceToken(token) {
				trustedSource = true
			}
		}
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	page := buildConfirmationPage(callback, trustedSource)
	fmt.Fprint(w, page)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, "ok")
}

func main() {
	secret := os.Getenv("SERVICE_SHARED_SECRET")
	if secret == "" {
		log.Fatal("SERVICE_SHARED_SECRET environment variable must be set")
	}
	serviceSecret = []byte(secret)

	mux := http.NewServeMux()
	mux.HandleFunc("/payment/callback", paymentCallbackHandler)
	mux.HandleFunc("/health", healthHandler)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Payment service starting on :8443")
	if err := server.ListenAndServe(); err != nil {
		log.Fatalf("server failed: %v", err)
	}
}
